    -- Check if the day is a weekday (Monday=2 to Friday=6 in Oracle's DOW, or use ISO week day)
    -- TRUNC(date, 'IW') returns the Monday of the week. If the day is Monday through Friday,
    -- the difference between the day and the start of its week (Monday) will be 0, 1, 2, 3, or 4.
    -- If it's Saturday (6) or Sunday (7), the difference will be 5 or 6.
    if to_char(l_day, 'D') in ('1', '2', '3', '4', '5') then -- Assuming 'D' returns 1=Sunday to 7=Saturday, or checking against ISO standard.
                                                            -- A safer way for M-F is checking DOW directly.
      -- Using TO_CHAR(date, 'DY') or checking day of week number (1=Sunday, 7=Saturday)
      -- If we assume standard Oracle NLS settings where DOW starts at 1=Sunday:
      if to_char(l_day, 'D') not in ('1', '7') then -- Assuming 'D' returns 1=Sunday, 7=Saturday
        l_count := l_count + 1;
      end if;
    end if;
    l_day := l_day + 1;
  end loop;
  return l_count;
