create or replace function t002_working_days(
  p_start in date,
  p_end   in date
) return pls_integer is
  -- Working days (Monday to Friday) between p_start and p_end, counting both dates.
  l_day   date        := trunc(p_start);
  l_count pls_integer := 0;
begin
  if p_start is null or p_end is null or trunc(p_end) < trunc(p_start) then
    return 0;
  end if;
  while l_day <= trunc(p_end) loop
    -- Check if the day is a weekday (Monday=2 to Friday=6 using ISO standard where Monday=1, Sunday=7, but Oracle's DOW can vary)
    -- Using TO_CHAR(date, 'DY') or checking the day of week number (1=Sunday, 7=Saturday) is common.
    -- For standard Oracle behavior where DOW starts at 1=Sunday, 7=Saturday:
    if to_char(l_day, 'D') in ('2', '3', '4', '5', '6') then -- 2=Mon, 3=Tue, 4=Wed, 5=Thu, 6=Fri (assuming 1=Sun, 7=Sat)
      l_count := l_count + 1;
    end if;
    l_day := l_day + 1;
  end loop;
  return l_count;
end t002_working_days;
/
